fn isqrt(n: i32) -> i32 {
    if n <= 0 { return 0; }
    let mut x: i32 = n;
    let mut y: i32 = (x + 1) / 2;
    while y < x {
        x = y;
        y = (x + n / x) / 2;
    }
    x
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cell: i32 = 8;
    let ax: i32 = w / 2 - 40;
    let ay: i32 = h / 2;
    let bx: i32 = host::display::pointer_x();
    let by: i32 = host::display::pointer_y();
    let mut cy: i32 = 0;
    while cy < h {
        let mut cx: i32 = 0;
        while cx < w {
            let x: i32 = cx + cell / 2;
            let y: i32 = cy + cell / 2;
            let d1: i32 = isqrt((x - ax) * (x - ax) + (y - ay) * (y - ay));
            let d2: i32 = isqrt((x - bx) * (x - bx) + (y - by) * (y - by));
            let p1: i32 = (d1 / 12) & 1;
            let p2: i32 = (d2 / 12) & 1;
            let c: i32 = if (p1 ^ p2) == 1 { 0xf0f0f0 } else { 0x181818 };
            host::display::fill_rect(cx, cy, cell, cell, c);
            cx = cx + cell;
        }
        cy = cy + cell;
    }
    host::display::present();
}
